fn uniq(it: impl Iterator<Item = &'static str>) -> Vec<&'static str> {
    let mut out: Vec<&'static str> = Vec::new();
    for s in it {
        if !out.contains(&s) {
            out.push(s);
        }
    }
    out
}

/// Standards in catalogue order.
pub fn standards() -> Vec<&'static str> {
    uniq(CATALOGUE.iter().map(|c| c.standard))
}

pub fn categories(standard: &str) -> Vec<&'static str> {
    uniq(CATALOGUE.iter().filter(|c| c.standard == standard).map(|c| c.category))
}

pub fn classes(standard: &str, category: &str) -> Vec<&'static str> {
    uniq(CATALOGUE.iter().filter(|c| c.standard == standard && c.category == category).map(|c| c.class))
}

pub fn components(standard: &str, category: &str, class: &str) -> Vec<&'static Component> {
    CATALOGUE.iter().filter(|c| c.standard == standard && c.category == category && c.class == class).collect()
}

/// The catalogue entry of a spec.
pub fn component(spec: &StandardSpec) -> Option<&'static Component> {
    CATALOGUE.iter().find(|c| c.standard == spec.standard && c.category == spec.category && c.class == spec.class && c.name == spec.component)
}

impl StandardSpec {
    /// A spec for a component with its default size (the middle one) and length.
    pub fn new(c: &Component) -> Self {
        let size = &c.sizes[c.sizes.len().saturating_sub(1) / 2];
        StandardSpec {
            standard: c.standard.into(),
            category: c.category.into(),
            class: c.class.into(),
            component: c.name.into(),
            size: size.name.into(),
            length: c.default_length(size),
        }
    }

    /// Instance name, like Onshape's "<component> - <size> x <length>".
    pub fn part_name(&self) -> String {
        let size = if component(self).is_some_and(|c| c.inch) { format!("{} in", self.size) } else { self.size.clone() };
        match &self.length {
            Some(l) => format!("{} - {size} x {l}", self.component),
            None => format!("{} - {size}", self.component),
        }
    }

    /// Change the size, keeping the length when it is still offered.
    pub fn set_size(&mut self, size: &str) {
        self.size = size.to_string();
        if let Some(c) = component(self)
            && let Some(s) = c.size(size)
        {
            let lengths = c.lengths(s);
            if self.length.as_ref().is_none_or(|l| !lengths.contains(l)) {
                self.length = c.default_length(s);
            }
        }
    }
}

/// The spec as configuration values (keeps BOM rows of different sizes apart).
pub fn config_values(spec: &StandardSpec) -> ConfigValues {
    let mut v = ConfigValues::default();
    v.0.insert("Component".into(), spec.component.clone());
    v.0.insert("Size".into(), spec.size.clone());
    if let Some(l) = &spec.length {
        v.0.insert("Length".into(), l.clone());
    }
    v
}

/// Auto-size: the size fitting a hole or shaft of diameter `d` (meters).
/// Bolts and screws round down (no interference), nuts and washers round up.
pub fn auto_size(c: &Component, d: f64) -> Option<&'static str> {
    let tol = 1e-6;
    let dm = |s: &Size| c.diameter_m(s);
    if c.shape == Shape::Washer {
        // Washers go with the bolt that fits: their nominal (bolt) size rounds down.
        let nominal = |s: &Size| nominal_m(c, s);
        c.sizes.iter().filter(|s| nominal(s) <= d + tol && nominal(s) >= d * 0.6).max_by(|a, b| nominal(a).total_cmp(&nominal(b))).map(|s| s.name)
    } else if c.shape.fits_over() {
        c.sizes.iter().filter(|s| dm(s) >= d - tol).min_by(|a, b| dm(a).total_cmp(&dm(b))).map(|s| s.name)
    } else {
        c.sizes.iter().filter(|s| dm(s) <= d + tol && dm(s) >= d * 0.6).max_by(|a, b| dm(a).total_cmp(&dm(b))).map(|s| s.name)
    }
}

/// Nominal (bolt) diameter of a size in meters: "M6" is 6 mm, "1/4" a
/// quarter inch; other names use the size's diameter.
fn nominal_m(c: &Component, s: &Size) -> f64 {
    if let Some(mm) = s.name.strip_prefix('M').and_then(|v| v.parse::<f64>().ok()) {
        return mm * 1e-3;
    }
    if c.inch
        && let Some(v) = length_value(&format!("{} in", s.name))
    {
        return v;
    }
    c.diameter_m(s)
}

/// Message when auto-size finds nothing (Onshape's wording).
pub const NO_MATCHING_SIZE: &str = "Unable to find matching size for selection. Selection may be too small or large for specific component";

fn mm(v: f64) -> ParamValue {
    ParamValue::Expr(ExprValue::new(format!("{} mm", (v * 1e6).round() / 1e6)))
}

/// The one-feature Part Studio generating a standard part (plus its mate
/// connectors). `None` for an unknown spec.
pub fn part_studio(spec: &StandardSpec) -> Option<PartStudio> {
    let c = component(spec)?;
    let s = c.size(&spec.size)?;
    let u = c.unit();
    let units = UnitPrefs::default();
    scripts();
    let mut ps = PartStudio::new();
    let mut f = ps.new_feature(&crate::custom::type_id(STANDARD_TAB, c.shape.feature()), &units)?;
    f.id = PART_FEATURE;
    f.name = spec.part_name();
    f.params.set("d", mm(s.d * u));
    f.params.set("a", mm(s.a * u));
    f.params.set("b", mm(s.b * u));
    f.params.set("c", mm(s.c * u));
    let len = spec.length.as_deref().and_then(length_value).unwrap_or(3.0 * s.d * u * 1e-3);
    f.params.set("l", mm(len * 1e3));
    ps.features.push(f);
    // Explicit mate connectors with the primary axis out of the contact
    // face (mates oppose the Z axes): under the head pointing down the shank
    // (countersunk: flush with the top), nuts and washers on both faces.
    let mut tops = vec![0.0];
    if !c.shape.has_length() {
        tops.push(s.b * u);
    }
    for (i, z) in tops.into_iter().enumerate() {
        let mut m = ps.new_feature("mateConnector", &units)?;
        m.id = FeatureId(PART_FEATURE.0 + 1 + i as u64);
        m.params.set("originQuery", ParamValue::Query(vec![crate::reference::Reference::Origin]));
        if i == 0 {
            m.params.set("flipPrimary", ParamValue::Bool(true));
        }
        if z != 0.0 {
            m.params.set("transform", ParamValue::Bool(true));
            m.params.set("translationZ", mm(z));
        }
        ps.features.push(m);
    }
    Some(ps)
}

/// The built-in Feature Studio, compiled once (registers the feature types).
pub fn scripts() -> Arc<DocumentScripts> {
    static SCRIPTS: LazyLock<Arc<DocumentScripts>> = LazyLock::new(|| {
        let mut doc = Document::new();
        doc.tabs.clear();
        doc.settings.tab_order.clear();
        let id = doc.add_tab("Standard content", TabContent::FeatureStudio(crate::custom::FeatureStudio::new(SOURCE)));
        if let Some(t) = doc.tab_mut(id) {
            t.id = STANDARD_TAB;
        }
        DocumentScripts::from_document(&doc)
    });
    SCRIPTS.clone()
}

/// Regenerate a standard part (the error says why it failed).
pub fn regenerate(spec: &StandardSpec) -> Result<RegenResult, String> {
    let scripts = scripts();
    if let Some(e) = scripts.studios().find_map(|(_, _, c)| c.first_error().map(|d| d.to_string())) {
        return Err(format!("Standard content script: {e}"));
    }
    let ps = part_studio(spec).ok_or("Unknown standard content item")?;
    let provider: Arc<dyn CustomFeatureProvider> = scripts;
    let opts = RegenOptions { custom_features: Some(provider), ..Default::default() };
    let r = Regenerator::new().regenerate(&ps, &ConfigValues::default(), &UnitPrefs::default(), &opts);
    if part_body(&r).is_none() {
        let why: Vec<String> = r.display.features.iter().filter_map(|f| f.message.clone()).collect();
        let bodies: Vec<String> = r.context.bodies.iter().map(|b| format!("{:?}", b.id)).collect();
        let notices: Vec<String> = crate::custom::run::outputs().values().flat_map(|o| o.notices.iter().map(|n| format!("{} {}: {}", n.module, n.pos, n.message))).collect();
        return Err(format!("{} was not generated: {} (bodies: {}; notices: {})", spec.part_name(), why.join("; "), bodies.join(", "), notices.join(" | ")));
    }
    Ok(r)
}

/// Script generating the standard parts. Every part has its mate connector
/// origin at the Part Studio origin with the head (or the part) above it.
pub const SOURCE: &str = r#"FeatureScript 3095;
import(path : "onshape/std/geometry.fs", version : "3095.0");

// Built-in standard content (fasteners). Parameters: d nominal diameter;
// a, b, c per shape; l length. Parts are built along Z, the head on z = 0.

const ORIGIN_2D = vector(0, 0) * meter;
const Z = 0 * meter;

function cylinderZ(context is Context, id is Id, z0 is ValueWithUnits, z1 is ValueWithUnits, r is ValueWithUnits) returns Query
{
    fCylinder(context, id, { "bottomCenter" : vector(Z, Z, z0), "topCenter" : vector(Z, Z, z1), "radius" : r });
    return qCreatedBy(id, EntityType.BODY);
}

/** A hexagonal prism, across flats `s`, from z0 to z0 + h. */
function hexPrism(context is Context, id is Id, z0 is ValueWithUnits, h is ValueWithUnits, s is ValueWithUnits) returns Query
{
    var p = XY_PLANE;
    p.origin[2] = z0;
    const sketch = newSketchOnPlane(context, id + "sketch", { "sketchPlane" : p });
    skRegularPolygon(sketch, "hex", { "center" : ORIGIN_2D, "firstVertex" : vector(s / sqrt(3), Z), "sides" : 6 });
    skSolve(sketch);
    opExtrude(context, id + "extrude", { "entities" : qSketchRegion(id + "sketch"), "direction" : vector(0, 0, 1), "endBound" : BoundingType.BLIND, "endDepth" : h });
    opDeleteBodies(context, id + "deleteSketch", { "entities" : qCreatedBy(id + "sketch", EntityType.BODY) });
    return qCreatedBy(id + "extrude", EntityType.BODY);
}

/** A closed polygon of (radius, z) points revolved about Z. */
function revolveZ(context is Context, id is Id, points is array) returns Query
{
    const sketch = newSketchOnPlane(context, id + "sketch", { "sketchPlane" : plane(vector(Z, Z, Z), vector(0, -1, 0), vector(1, 0, 0)) });
    skPolyline(sketch, "profile", { "points" : append(points, points[0]) });
    skSolve(sketch);
    opRevolve(context, id + "revolve", { "entities" : qSketchRegion(id + "sketch"), "axis" : line(vector(Z, Z, Z), vector(0, 0, 1)), "angleForward" : 2 * PI * radian });
    opDeleteBodies(context, id + "deleteSketch", { "entities" : qCreatedBy(id + "sketch", EntityType.BODY) });
    return qCreatedBy(id + "revolve", EntityType.BODY);
}

function intersect(context is Context, id is Id, target is Query, tool is Query)
{
    opBoolean(context, id, { "tools" : tool, "targets" : target, "operationType" : BooleanOperationType.INTERSECTION });
}

function subtract(context is Context, id is Id, target is Query, tool is Query)
{
    opBoolean(context, id, { "tools" : tool, "targets" : target, "operationType" : BooleanOperationType.SUBTRACTION });
}

/** 30 degree chamfer on the corners of a hex prism (z0 .. z0 + h), on its top (and bottom when `both`). */
function hexChamfer(context is Context, id is Id, body is Query, z0 is ValueWithUnits, h is ValueWithUnits, s is ValueWithUnits, both is boolean)
{
    const r = s * 0.5 * 0.95;
    const t = h * 1.732;
    const top = z0 + h;
    intersect(context, id + "top", body, revolveZ(context, id + "topCone", [vector(Z, top), vector(r, top), vector(r + t, z0), vector(Z, z0)]));
    if (both)
        intersect(context, id + "bottom", body, revolveZ(context, id + "bottomCone", [vector(Z, z0), vector(r, z0), vector(r + t, top), vector(Z, top)]));
}

function withShank(context is Context, id is Id, head is Query, z0 is ValueWithUnits, d is ValueWithUnits, l is ValueWithUnits)
{
    const shank = cylinderZ(context, id + "shank", z0 - l, z0, d / 2);
    opBoolean(context, id + "join", { "tools" : qUnion([head, shank]), "operationType" : BooleanOperationType.UNION });
}

predicate fastenerParameters(definition is map)
{
    annotation { "Name" : "Diameter" }
    isLength(definition.d, NONNEGATIVE_LENGTH_BOUNDS);
    annotation { "Name" : "A" }
    isLength(definition.a, NONNEGATIVE_ZERO_INCLUSIVE_LENGTH_BOUNDS);
    annotation { "Name" : "B" }
    isLength(definition.b, NONNEGATIVE_ZERO_INCLUSIVE_LENGTH_BOUNDS);
    annotation { "Name" : "C" }
    isLength(definition.c, NONNEGATIVE_ZERO_INCLUSIVE_LENGTH_BOUNDS);
    annotation { "Name" : "Length" }
    isLength(definition.l, NONNEGATIVE_LENGTH_BOUNDS);
}

annotation { "Feature Type Name" : "Hex bolt" }
export const hexBolt = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
        annotation { "Name" : "Diameter" }
        isLength(definition.d, NONNEGATIVE_LENGTH_BOUNDS);
        annotation { "Name" : "A" }
        isLength(definition.a, NONNEGATIVE_ZERO_INCLUSIVE_LENGTH_BOUNDS);
        annotation { "Name" : "B" }
        isLength(definition.b, NONNEGATIVE_ZERO_INCLUSIVE_LENGTH_BOUNDS);
        annotation { "Name" : "C" }
        isLength(definition.c, NONNEGATIVE_ZERO_INCLUSIVE_LENGTH_BOUNDS);
        annotation { "Name" : "Length" }
        isLength(definition.l, NONNEGATIVE_LENGTH_BOUNDS);
    }
    {
        const head = hexPrism(context, id + "head", Z, definition.b, definition.a);
        hexChamfer(context, id + "chamfer", head, Z, definition.b, definition.a, false);
        withShank(context, id, head, Z, definition.d, definition.l);
    });

annotation { "Feature Type Name" : "Socket head screw" }
export const socketHeadScrew = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
        fastenerParameters(definition);
    }
    {
        const head = cylinderZ(context, id + "head", Z, definition.b, definition.a / 2);
        subtract(context, id + "socketCut", head, hexPrism(context, id + "socket", definition.b * 0.45, definition.b, definition.c));
        withShank(context, id, head, Z, definition.d, definition.l);
    });

annotation { "Feature Type Name" : "Button head screw" }
export const buttonHeadScrew = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
        fastenerParameters(definition);
    }
    {
        const r = definition.a / 2;
        const b = definition.b;
        const big = (r * r + b * b) / (2 * b);
        const head = cylinderZ(context, id + "head", Z, b, r);
        opSphere(context, id + "dome", { "center" : vector(Z, Z, b - big), "radius" : big });
        intersect(context, id + "domeCut", head, qCreatedBy(id + "dome", EntityType.BODY));
        subtract(context, id + "socketCut", head, hexPrism(context, id + "socket", b * 0.35, b, definition.c));
        withShank(context, id, head, Z, definition.d, definition.l);
    });

annotation { "Feature Type Name" : "Countersunk screw" }
export const countersunkScrew = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
        fastenerParameters(definition);
    }
    {
        const k = (definition.a - definition.d) / 2;
        const head = revolveZ(context, id + "head", [vector(Z, Z), vector(definition.a / 2, Z), vector(definition.d / 2, -k), vector(Z, -k)]);
        subtract(context, id + "socketCut", head, hexPrism(context, id + "socket", -k * 0.8, k, definition.c));
        withShank(context, id, head, -k, definition.d, definition.l - k);
    });

annotation { "Feature Type Name" : "Set screw" }
export const setScrew = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
        fastenerParameters(definition);
    }
    {
        const body = cylinderZ(context, id + "body", -definition.l, Z, definition.d / 2);
        subtract(context, id + "socketCut", body, hexPrism(context, id + "socket", -definition.d * 0.6, definition.d, definition.c));
    });

annotation { "Feature Type Name" : "Hex nut" }
export const hexNut = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
        fastenerParameters(definition);
    }
    {
        const nut = hexPrism(context, id + "nut", Z, definition.b, definition.a);
        hexChamfer(context, id + "chamfer", nut, Z, definition.b, definition.a, true);
        subtract(context, id + "holeCut", nut, cylinderZ(context, id + "hole", -definition.b, definition.b * 2, definition.d / 2));
    });

annotation { "Feature Type Name" : "Washer" }
export const washer = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
        fastenerParameters(definition);
    }
    {
        const w = cylinderZ(context, id + "washer", Z, definition.b, definition.a / 2);
        subtract(context, id + "holeCut", w, cylinderZ(context, id + "hole", -definition.b, definition.b * 2, definition.d / 2));
    });

annotation { "Feature Type Name" : "Pin" }
export const pin = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
        fastenerParameters(definition);
    }
    {
        cylinderZ(context, id + "pin", -definition.l, Z, definition.d / 2);
    });
"#;

/// Mate connector of a standard part (index 0: under the head / bottom face;
/// 1: top face of nuts and washers).
pub fn connector_reference(index: u64) -> crate::reference::Reference {
    crate::reference::Reference::MateConnector { feature: FeatureId(PART_FEATURE.0 + 1 + index), index: 0 }
}

/// Holes to fasten standard content to, from a picked entity (studio
/// coordinates): a circular edge or cylindrical face gives one hole (the
/// end whose face points most along `toward`, the viewer), a planar face
/// every circular hole in it. Each hole: its connector (center of the
/// circle, primary axis out of the face around it) and diameter.
pub fn hole_connectors(ctx: &Arc<crate::regen::context::Context>, body: Option<&BodyId>, on: &crate::reference::Reference, toward: glam::DVec3, units: &UnitPrefs) -> Vec<(super::eval::InferencePoint, f64)> {
    use crate::reference::{Inference, Reference};
    use noshape_kernel::{Curve, ShapeType, Surface};
    let Some(b) = ctx.bodies.iter().find(|b| {
        body.is_none_or(|id| &b.id == id)
            && match on {
                Reference::Face(n) => !b.find_faces(n).is_empty(),
                Reference::Edge(n) => !b.find_edges(n).is_empty(),
                _ => false,
            }
    }) else {
        return Vec::new();
    };
    let Ok(edge_faces) = b.shape.edge_faces() else { return Vec::new() };
    let surface = |fi: u32| b.shape.sub_shape(ShapeType::Face, fi as usize).ok().and_then(|f| f.face_surface().ok());
    let planar = |fi: u32| matches!(surface(fi), Some(Surface::Plane(_)));
    let circle = |ei: usize| match b.shape.sub_shape(ShapeType::Edge, ei).ok().and_then(|e| e.edge_info().ok()).map(|i| i.curve) {
        Some(Curve::Circle { radius, .. }) => Some(radius),
        _ => None,
    };
    let cylinder = |fi: u32| matches!(surface(fi), Some(Surface::Cylinder { .. }));
    let circles_of = |fi: u32| edge_faces.iter().enumerate().filter(move |(_, f)| f.contains(&fi)).map(|(e, _)| e).filter(|e| circle(*e).is_some()).collect::<Vec<_>>();
    let other = |ei: usize, fi: u32| edge_faces[ei].iter().copied().find(|f| *f != fi);
    // A hole's end at circular edge `ei` of cylinder `cyl`: the edge and the
    // planar face around it, through a fillet or chamfer ring if there is one.
    let end = |ei: usize, cyl: u32| -> Option<(usize, u32)> {
        let g = other(ei, cyl)?;
        if planar(g) {
            return Some((ei, g));
        }
        circles_of(g).into_iter().filter(|e| *e != ei).find_map(|e| other(e, g).filter(|h| planar(*h)).map(|h| (e, h)))
    };
    // The cylinder behind a ring face (fillet or chamfer around a hole).
    let ring_cylinder = |g: u32| circles_of(g).into_iter().find_map(|e| other(e, g).filter(|c| cylinder(*c)).map(|c| (e, c)));
    // (edge, planar face around it, diameter)
    let mut holes: Vec<(usize, u32, f64)> = Vec::new();
    // Planar face: every hole in it; edge or cylinder: one end of one hole.
    let mut single = true;
    let cyl_ends = |cyl: u32, holes: &mut Vec<(usize, u32, f64)>| {
        for e in circles_of(cyl) {
            if let (Some((edge, face)), Some(r)) = (end(e, cyl), circle(e)) {
                holes.push((edge, face, 2.0 * r));
            }
        }
    };
    match on {
        Reference::Edge(n) => {
            if let Some(&ei) = b.find_edges(n).first()
                && circle(ei).is_some()
            {
                let faces = &edge_faces[ei];
                if let Some(&c) = faces.iter().find(|f| cylinder(**f)) {
                    cyl_ends(c, &mut holes);
                } else if let Some((_, c)) = faces.iter().find_map(|f| ring_cylinder(*f)) {
                    cyl_ends(c, &mut holes);
                }
            }
        }
        Reference::Face(n) => {
            let Some(&fi) = b.find_faces(n).first() else { return Vec::new() };
            let fi = fi as u32;
            if cylinder(fi) {
                cyl_ends(fi, &mut holes);
            } else if planar(fi) {
                single = false;
                for e in circles_of(fi) {
                    let Some(g) = other(e, fi) else { continue };
                    let d = if cylinder(g) { circle(e) } else { ring_cylinder(g).and_then(|(ce, _)| circle(ce)) };
                    if let Some(r) = d {
                        holes.push((e, fi, 2.0 * r));
                    }
                }
            } else if let Some((_, c)) = ring_cylinder(fi) {
                cyl_ends(c, &mut holes);
            }
        }
        _ => {}
    }
    let mut out: Vec<(super::eval::InferencePoint, f64)> = Vec::new();
    for (ei, fi, d) in holes {
        let (Some(en), Some(fname)) = (b.edges.get(ei), b.faces.get(fi as usize)) else { continue };
        let reference = Reference::Implicit { on: Box::new(Reference::Edge((**en).clone())), inference: Inference::Center };
        let align = Reference::Face((**fname).clone());
        if let Some(frame) = super::eval::resolve_connector_aligned(ctx, body, &reference, Some(&align), units) {
            out.push((super::eval::InferencePoint { reference, align: Some(align), frame }, d));
        }
    }
    if single && out.len() > 1 {
        let best = out.iter().enumerate().max_by(|a, c| a.1.0.frame.z().dot(toward).total_cmp(&c.1.0.frame.z().dot(toward))).map(|(i, _)| i).unwrap_or(0);
        out = vec![out.swap_remove(best)];
    }
    out
}

